onfig.pin_href = CAM_PIN_HREF;\n58\t    config.pin_sccb_sda = CAM_PIN_SIOD;\n59\t    config.pin_sccb_scl = CAM_PIN_SIOC;\n60\t    config.pin_pwdn = CAM_PIN_PWDN;\n61\t    config.pin_reset = CAM_PIN_RESET;\n62\t    config.xclk_freq_hz = 20000000;\n63\t    config.pixel_format = PIXFORMAT_RGB565;\n64\t    config.frame_size = FRAMESIZE_QVGA;\n65\t    config.jpeg_quality = 12;\n66\t    config.fb_count = 2;\n67\t    config.grab_mode = CAMERA_GRAB_WHEN_EMPTY;\n68\t    config.fb_location = CAMERA_FB_IN_PSRAM;\n69\t\n70\t    esp_err_t err = esp_camera_init(&config);\n71\t    if (err != ESP_OK) {\n72\t        ESP_LOGE(TAG, \"Camera init failed with error 0x%x\", err);\n73\t        return err;\n74\t    }\n75\t\n76\t    // 设置摄像头参数\n77\t    sensor_t *s = esp_camera_sensor_get();\n78\t    if (s) {\n79\t        s->set_vflip(s, 0);      // 垂直翻转\n80\t        s->set_hmirror(s, 1);    // 水平镜像\n81\t        s->set_brightness(s, 1); // 亮度\n82\t        s->set_saturation(s, 0); // 饱和度\n83\t    }\n84\t\n85\t    ESP_LOGI(TAG, \"Camera initialized successfully\");\n86\t    return ESP_OK;\n87\t}\n88\t\n89\t/**\n90\t * @brief 人脸检测任务\n91\t * @param pvParameters 任务参数\n92\t */\n93\tstatic void face_detection_task(void *pvParameters)\n94\t{\n95\t    ESP_LOGI(TAG, \"Face detection task started\");\n96\t\n97\t    while (1) {\n98\t        // 获取摄像头帧\n99\t        camera_fb_t *fb = esp_camera_fb_get();\n100\t        if (!fb) {\n101\t            ESP_LOGE(TAG, \"Camera capture failed\");\n102\t            vTaskDelay(pdMS_TO_TICKS(100));\n103\t            continue;\n104\t        }\n105\t\n106\t        // 在这里添加人脸检测逻辑\n107\t        // 可以使用 esp-who 的人脸检测库\n108\t        // 例如：who_detect_face(fb->buf, fb->width, fb->height);\n109\t\n110\t        ESP_LOGI(TAG, \"Captured frame: %dx%d, %d bytes\",\n111\t                 fb->width, fb->height, fb->len);\n112\t\n113\t        // 释放帧缓冲区\n114\t        esp_camera_fb_return(fb);\n115\t\n116\t        // 延时\n117\t        vTaskDelay(pdMS_TO_TICKS(100));\n118\t    }\n119\t}\n120\t\n121\t/**\n122\t * @brief 主函数\n123\t */\n124\textern \"C\" void app_main(void)\n125\t{\n126\t    ESP_LOGI(TAG, \"Starting ESP32-S3 Eye Face Detection\");\n127\t\n128\t    // 初始化摄像头\n129\t    esp_err_t err = init_camera();\n130\t    if (err != ESP_OK) {\n131\t        ESP_LOGE(TAG, \"Failed to initialize camera\");\n132\t        return;\n133\t    }\n134\t\n135\t    // 创建人脸检测任务\n136\t    xTaskCreatePinnedToCore(\n137\t        face_detection_task,    // 任务函数\n138\t        \"face_detection\",       // 任务名称\n139\t        8192,                   // 堆栈大小\n140\t        NULL,                   // 任务参数\n141\t        5,                      // 任务优先级\n142\t        NULL,                   // 任务句柄\n143\t        0                       // 核心 ID\n144\t    );\n145\t\n146\t    ESP_LOGI(TAG, \"Face detection task created\");\n147\t}", "is_error": false}
