static bool ag_is_skin(uint16_t rgb565)
{
  int r5 = (rgb565 >> 11) & 0x1f;
  int g6 = (rgb565 >> 5) & 0x3f;
  int b5 = rgb565 & 0x1f;
  int r = (r5 * 255) / 31;
  int g = (g6 * 255) / 63;
  int b = (b5 * 255) / 31;
  int maximum = r > g ? r : g;
  int minimum;

