        }
      face = worker->face;
      last_camera_ms = worker->last_camera_ms;
      pthread_mutex_unlock(&worker->lock);

      if (!have_frame)
        {
          memset(worker->draw_pixels, 0, AG_FRAME_BYTES);
          memset(&face, 0, sizeof(face));
        }

      status.activity_on = (heartbeat++ & 1u) != 0;
