    {
      free(worker->latest_pixels);
      free(worker->draw_pixels);
      worker->latest_pixels = NULL;
      worker->draw_pixels = NULL;
      return -1;
    }

  memset(worker->latest_pixels, 0, AG_FRAME_BYTES);
  memset(worker->draw_pixels, 0, AG_FRAME_BYTES);
