int round_half_even(float value)
{
#if CONFIG_ESP32P4_BOOST
    int ret;
    __asm__ volatile("fcvt.w.s %0, %1, rne" : "=r"(ret) : "f"(value));
    return ret;
#else
    float rounded;
    if (value < 0) {
        rounded = value - 0.5f;
    } else {
        rounded = value + 0.5f;
    }

    int int_part = (int)rounded;
    if (fabsf(rounded - int_part) < 1e-6) {
        if ((int_part & 1) != 0) {
            if (value < 0)
                int_part++;
            else
                int_part--;
        }
    }
    return int_part;
#endif
}

