    DL_IMAGE_PIX_TYPE_GRAY_QINT8,
    DL_IMAGE_PIX_TYPE_GRAY_QINT16,
    DL_IMAGE_PIX_TYPE_RGB565,
    DL_IMAGE_PIX_TYPE_HSV,
} pix_type_t;

typedef struct {
    void *data;
    uint16_t width;
    uint16_t height;
    pix_type_t pix_type;
} img_t;

