constexpr unsigned int kInferenceInterval = 3;
constexpr unsigned int kMaximumFaces = 8;

HumanFaceDetect *g_detector;
ag_vision_result g_cached_result;
unsigned int g_frame_counter;

/* Temporary hardware acceptance marker: an actual model inference must return
 * before execution can reach this uniquely named loop.  It is removed again
 * after the saved PC is sampled through the USB reset path. */

__attribute__((noinline)) void espdl_hardware_acceptance_pass()
{
  sched_lock();
  for (;;)
    {
      __asm__ __volatile__("nop");
    }
}

uint16_t clip_coordinate(int value, uint16_t limit)
{
  if (value < 0)
    {
      return 0;
    }

  if (value >= limit)
    {
      return limit - 1;
    }

  return static_cast<uint16_t>(value);
}

} // namespace

